const body = $json.body || $json;
const text = (body.text || '').trim();

if (!text) throw new Error('400: No confirmation text provided');

const systemContent = `You are a travel booking data extraction assistant for Voyage Genie.
Extract structured trip information from the booking confirmation below.

Return ONLY a single valid JSON object — no markdown, no explanation, no code fences.

Required JSON keys (use empty string "" if not found):
{
  "name":         "descriptive trip name, e.g. Maui Family Vacation 2026",
  "destination":  "city and/or country, e.g. Maui, Hawaii",
  "tripType":     "exactly one of: Tropical Resort | Cruise Adventure | Airbnb Getaway | Adventure Trip | City Break | Road Trip | Business Trip | Other",
  "startDate":    "YYYY-MM-DD or empty string",
  "endDate":      "YYYY-MM-DD or empty string",
  "groupSize":    "integer as string or empty string",
  "budget":       "total numeric amount only — no $ or commas, e.g. 5240.00 — or empty string",
  "participants": "comma-separated full names or empty string",
  "bookingRef":   "confirmation / booking / reservation number or empty string",
  "agent":        "travel agent name, airline, hotel brand, or booking platform or empty string",
  "notes":        "flight numbers, hotel name, room type, special requests, or any other key details"
}`;

return [{
  json: {
    systemContent,
    confirmationText: text,
    user_id: body.user_id || null,
    save_to_supabase: body.save_to_supabase !== false
  }
}];

const raw = $node['OpenAI Extract'].json.message?.content || '';

// Strip markdown fences if present
const clean = raw.replace(/^```[a-z]*\n?/gm, '').replace(/```\s*$/gm, '').trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch(e) {
  const match = clean.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('ChatGPT did not return valid JSON: ' + clean.slice(0, 200));
  try { parsed = JSON.parse(match[0]); }
  catch { throw new Error('Could not parse JSON: ' + clean.slice(0, 200)); }
}

// Build participants array
const participants = (parsed.participants || '')
  .split(',').map(s => s.trim()).filter(Boolean);

// Build trip_data matching Voyage Genie schema
const tripData = {
  name:          parsed.name        || '',
  tripType:      parsed.tripType    || 'Other',
  destination:   parsed.destination || '',
  startDate:     parsed.startDate   || '',
  endDate:       parsed.endDate     || '',
  groupSize:     parsed.groupSize   ? Number(parsed.groupSize) : (participants.length || ''),
  budget:        parsed.budget      ? Number(parsed.budget)    : '',
  participants,
  people:        participants.map(n => ({ name: n, payer: n })),
  bookingRef:    parsed.bookingRef  || '',
  agent:         parsed.agent       || '',
  notes:         parsed.notes       || '',
  expenses:      [],
  addedManually: true,
  parsedByAI:    true,
  parsedBy:      'chatgpt',
  createdAt:     new Date().toISOString()
};

const user_id = $('Prepare Messages').first().json.user_id;
const save    = $('Prepare Messages').first().json.save_to_supabase;

return [{ json: { tripData, trip_name: parsed.name || 'My Trip', user_id, save } }];
